// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DownloadDocument Скачать файл документа (владелец-организация или admin)
	// (GET /documents/{documentId}/file)
	DownloadDocument(ctx context.Context, request DownloadDocumentRequestObject) (DownloadDocumentResponseObject, error)
	// GetMyOrganization Профиль своей компании
	// (GET /organizations/me)
	GetMyOrganization(ctx context.Context, request GetMyOrganizationRequestObject) (GetMyOrganizationResponseObject, error)
	// UpdateMyOrganization Редактирование профиля (только в статусах draft / rejected)
	// (PATCH /organizations/me)
	UpdateMyOrganization(ctx context.Context, request UpdateMyOrganizationRequestObject) (UpdateMyOrganizationResponseObject, error)
	// ListMyDocuments Загруженные KYC-документы своей компании
	// (GET /organizations/me/documents)
	ListMyDocuments(ctx context.Context, request ListMyDocumentsRequestObject) (ListMyDocumentsResponseObject, error)
	// UploadMyDocument Загрузить KYC-документ
	// (POST /organizations/me/documents)
	UploadMyDocument(ctx context.Context, request UploadMyDocumentRequestObject) (UploadMyDocumentResponseObject, error)
	// DeleteMyDocument Удалить свой документ (только в статусах draft / rejected)
	// (DELETE /organizations/me/documents/{documentId})
	DeleteMyDocument(ctx context.Context, request DeleteMyDocumentRequestObject) (DeleteMyDocumentResponseObject, error)
	// SubmitKYC Отправить компанию на верификацию
	// (POST /organizations/me/kyc/submit)
	SubmitKYC(ctx context.Context, request SubmitKYCRequestObject) (SubmitKYCResponseObject, error)
	// RegistryLookup Автозаполнение по реестру (ЕГРЮЛ через DaData для RU, GLEIF по LEI для остальных)
	// (GET /registry/lookup)
	RegistryLookup(ctx context.Context, request RegistryLookupRequestObject) (RegistryLookupResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// DownloadDocument operation middleware
func (sh *strictHandler) DownloadDocument(w http.ResponseWriter, r *http.Request, documentID DocumentID) {
	var request DownloadDocumentRequestObject

	request.DocumentID = documentID

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.DownloadDocument(ctx, request.(DownloadDocumentRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "DownloadDocument")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(DownloadDocumentResponseObject); ok {
		if err := validResponse.VisitDownloadDocumentResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

